#include <geist.h>
#include <geist_util.h>
#include <stdio.h>
int main(int argc, char **argv) {
    if (argc != 4) return 1;
    struct geist_backend *be = nullptr;
    struct geist_model *model = nullptr;
    struct geist_session *session = nullptr;
    const struct geist_session_opts opts = {.max_seq_len=128, .kv_mode=GEIST_KV_FP32};
    if (geist_backend_create(argv[2], nullptr, nullptr, &be) != GEIST_OK ||
        geist_model_load_with_opts(argv[1], be, &opts, &model) != GEIST_OK ||
        geist_session_create(model, be, &opts, &session) != GEIST_OK) return 2;
    geist_token_t tokens[64];
    size_t n = 0;
    if (geist_session_tokenize(session, "Hello this is a repeatable generation regression probe.", 64, tokens, &n) != GEIST_OK || n == 0 ||
        geist_session_prefill_tokens(session, n, tokens) != GEIST_OK) return 3;
    size_t vocab = 0;
    const float *logits = geist_session_peek_logits(&vocab, session);
    FILE *f = fopen(argv[3], "wb");
    if (f == nullptr || logits == nullptr || fwrite(&vocab, sizeof vocab, 1, f) != 1 || fwrite(logits, sizeof(float), vocab, f) != vocab) return 4;
    for (size_t i=0; i<8; i++) {
        geist_token_t token = -1;
        if (geist_session_decode_step(session, &token) != GEIST_OK || fwrite(&token, sizeof token, 1, f) != 1) return 5;
    }
    if (fclose(f) != 0) return 6;
    geist_session_destroy(session); geist_model_destroy(model); geist_backend_destroy(be);
    return 0;
}
